WITH metrics AS (SELECT *, ROUND(quantity / SUM(quantity) OVER (PARTITION BY order_id), 4) AS quantity_share, CUME_DIST() OVER (ORDER BY quantity DESC NULLS FIRST) AS quantity_cume_dist FROM order_items WHERE quantity = 6) SELECT s.id, s.product_id, s.quantity, s.unit_price, s.quantity_share, s.quantity_cume_dist, (SELECT MIN(x.quantity) FROM order_items x WHERE x.product_id = s.product_id) AS min_order_item_quantity FROM metrics s
